<script setup lang="ts">
import { printChallengeCertificate } from '~/utils/challengeExport'
definePageMeta({ layout: 'challenge' })
const { state, ready, rankings, anomalies, ties, assignAward, setResultsVisibility, teamEligible } = useChallenge()
const { t } = useI18n()
const { lt, number, date } = useChallengeFormat()
const { result, push } = useChallengeToast()
const localePath = useLocalePath()
useHead(() => ({ title: `${t('challenge.admin.resultsTitle')} - Gaming Lab` }))
const search = ref('')
const filtered = computed(() => rankings.value.filter(row => { const team = state.value?.teams.find(item => item.id === row.teamId); return `${lt(team?.name)} ${lt(state.value?.schools.find(school => school.id === team?.schoolId)?.name)}`.toLowerCase().includes(search.value.toLowerCase()) }))
const editable = computed(() => ['judging', 'results'].includes(state.value?.competition.phase || ''))
const tieOpen = ref(false)
const tiedTeamIds = ref<string[]>([])
const openTie = (teamIds: string[]) => { tiedTeamIds.value = [...teamIds]; tieOpen.value = true }
const certificateTeamId = ref('')
const certificateStudentId = ref('')
const certificateMembers = computed(() => { const team = state.value?.teams.find(item => item.id === certificateTeamId.value); return state.value?.students.filter(student => team?.memberIds.includes(student.id)) || [] })
watch(certificateTeamId, () => { certificateStudentId.value = certificateMembers.value[0]?.id || '' })
watch(rankings, rows => { if (!certificateTeamId.value && rows.length) certificateTeamId.value = rows[0]!.teamId }, { immediate: true })
const printCertificate = () => {
  const world = state.value
  const team = world?.teams.find(item => item.id === certificateTeamId.value)
  const student = certificateMembers.value.find(item => item.id === certificateStudentId.value)
  const ranking = rankings.value.find(item => item.teamId === team?.id)
  if (!world || !team || !student || !ranking) return
  const ok = printChallengeCertificate({ competition: lt(world.competition.title), student: lt(student.name), team: lt(team.name), school: lt(world.schools.find(school => school.id === team.schoolId)?.name), rank: number(ranking.rank), score: `${number(ranking.score)} / 100`, date: date(new Date()), title: t('challenge.admin.certificateTitle') })
  if (!ok) push('challenge.admin.popupBlocked', 'warning')
}
const publicationIssues = computed(() => {
  if (!state.value) return []
  const issues: string[] = []
  if (state.value.competition.phase !== 'results') issues.push(t('challenge.admin.publishPhaseRequired'))
  if (ties.value.length) issues.push(t('challenge.admin.publishTieRequired'))
  const teams = state.value.teams.filter(team => teamEligible(team.id) && state.value!.submissions.some(submission => submission.teamId === team.id && submission.status !== 'draft'))
  if (!teams.length || teams.some(team => (rankings.value.find(row => row.teamId === team.id)?.evaluationCount || 0) < 2)) issues.push(t('challenge.admin.publishEvaluationsRequired'))
  if (state.value.criteria.reduce((sum, item) => sum + item.weight, 0) !== 100) issues.push(t('challenge.admin.publishWeightsRequired'))
  return issues
})
</script>
<template>
  <div v-if="ready && state" class="challenge-page space-y-8"><div><h1 class="challenge-heading">{{ $t('challenge.admin.resultsTitle') }}</h1><p class="challenge-subtitle">{{ $t('challenge.admin.resultsIntro') }}</p></div>
    <section class="challenge-panel"><div class="flex flex-wrap items-center justify-between gap-4"><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.calibration') }}</h2><div class="flex gap-2"><ChallengeStatusPill :tone="anomalies.length ? 'warning' : 'success'">{{ $t('challenge.admin.anomalyCount', { count: number(anomalies.length) }) }}</ChallengeStatusPill><ChallengeStatusPill :tone="ties.length ? 'warning' : 'success'">{{ $t('challenge.admin.tieCount', { count: number(ties.length) }) }}</ChallengeStatusPill></div></div><p class="mt-3 text-sm">{{ $t('challenge.admin.calibrationHint') }}</p><label for="admin-ranking-search" class="challenge-label mt-5">{{ $t('challenge.admin.search') }}</label><input id="admin-ranking-search" v-model="search" type="search" class="challenge-field sm:max-w-md" :placeholder="$t('challenge.admin.searchEntities')" /><div v-if="filtered.length" class="mt-6 overflow-x-auto"><table class="w-full min-w-[700px] text-start text-sm"><thead><tr class="border-b border-gray-200 text-heading"><th class="px-3 py-3 text-start">{{ $t('challenge.admin.rank') }}</th><th class="px-3 py-3 text-start">{{ $t('challenge.admin.team') }}</th><th class="px-3 py-3 text-start">{{ $t('challenge.admin.judgeScores') }}</th><th class="px-3 py-3 text-start">{{ $t('challenge.admin.average') }}</th><th class="px-3 py-3 text-start">{{ $t('challenge.admin.spread') }}</th><th class="px-3 py-3 text-start">{{ $t('challenge.admin.flags') }}</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.teamId" class="border-b border-gray-100"><td class="px-3 py-4 font-bold">{{ number(row.rank) }}</td><td class="px-3 py-4"><strong>{{ lt(state.teams.find(team => team.id === row.teamId)?.name) }}</strong><p class="mt-1 text-xs">{{ lt(state.schools.find(school => school.id === state.teams.find(team => team.id === row.teamId)?.schoolId)?.name) }}</p></td><td class="px-3 py-4"><ul class="space-y-1"><li v-for="score in row.judgeScores" :key="score.judgeId" class="flex justify-between gap-3 text-xs"><span>{{ lt(state.judges.find(judge => judge.id === score.judgeId)?.name) }}</span><strong>{{ number(score.score) }}</strong></li></ul></td><td class="px-3 py-4 font-bold text-brand-deep">{{ number(row.score) }}</td><td class="px-3 py-4">{{ number(row.spread) }}</td><td class="px-3 py-4"><div class="flex flex-wrap gap-2"><ChallengeStatusPill v-if="row.isAnomaly" tone="warning">{{ $t('challenge.admin.anomaly') }}</ChallengeStatusPill><ChallengeStatusPill v-if="row.tied" tone="warning">{{ $t('challenge.admin.tie') }}</ChallengeStatusPill><ChallengeStatusPill v-if="!row.isAnomaly && !row.tied" tone="success">{{ $t('challenge.admin.clear') }}</ChallengeStatusPill></div></td></tr></tbody></table></div><ChallengeEmptyState v-else :title="$t('challenge.admin.noRankings')" :description="$t('challenge.admin.noRankingsHint')" icon="trophy" />
      <div v-if="ties.length" class="mt-6 space-y-3 border-t border-gray-200 pt-5"><article v-for="(group, index) in ties" :key="group.join('-')" class="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-amber-50 p-4"><div><h3 class="font-semibold">{{ $t('challenge.admin.tieGroup', { count: number(index + 1) }) }}</h3><p class="mt-1 text-sm">{{ group.map(id => lt(state.teams.find(team => team.id === id)?.name)).join(' · ') }}</p></div><button type="button" class="challenge-button-secondary" :disabled="!editable" @click="openTie(group)">{{ $t('challenge.admin.breakTie') }}</button></article></div>
    </section>
    <section class="challenge-panel"><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.specialAwards') }}</h2><p class="mt-2 text-sm">{{ $t('challenge.admin.awardsHint') }}</p><div class="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><div v-for="award in state.awards" :key="award.id"><label :for="`award-${award.id}`" class="challenge-label">{{ lt(award.name) }}</label><select :id="`award-${award.id}`" :value="award.teamId || ''" class="challenge-field" :disabled="!editable" @change="result(assignAward(award.id, ($event.target as HTMLSelectElement).value || null), 'challenge.admin.awardSaved')"><option value="">{{ $t('challenge.admin.noAwardWinner') }}</option><option v-for="row in rankings" :key="row.teamId" :value="row.teamId">{{ lt(state.teams.find(team => team.id === row.teamId)?.name) }}</option></select></div></div><p v-if="!editable" class="mt-4 text-sm text-amber-900">{{ $t('challenge.admin.resultsLocked') }}</p></section>
    <section class="challenge-panel"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.publicVisibility') }}</h2><p class="mt-2 text-sm">{{ $t('challenge.admin.visibilityHint') }}</p></div><ChallengeStatusPill :tone="state.competition.resultsVisibility === 'published' ? 'success' : 'neutral'">{{ $t(`challenge.status.${state.competition.resultsVisibility}`) }}</ChallengeStatusPill></div><ul v-if="publicationIssues.length" class="mt-4 list-disc space-y-2 ps-5 text-sm text-amber-900"><li v-for="issue in publicationIssues" :key="issue">{{ issue }}</li></ul><div class="mt-5 flex flex-wrap gap-3"><button type="button" class="challenge-button" :disabled="publicationIssues.length > 0 || state.competition.resultsVisibility === 'published'" @click="result(setResultsVisibility(true), 'challenge.admin.resultsPublished')">{{ $t('challenge.admin.publishResults') }}</button><button type="button" class="challenge-button-secondary" :disabled="state.competition.resultsVisibility === 'hidden' || state.competition.phase === 'archived'" @click="result(setResultsVisibility(false), 'challenge.admin.resultsHidden')">{{ $t('challenge.admin.hideResults') }}</button><NuxtLink :to="localePath('/challenge/results')" class="challenge-button-secondary">{{ $t('challenge.admin.viewPublicResults') }}</NuxtLink></div></section>
    <section class="challenge-panel"><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.certificates') }}</h2><p class="mt-2 text-sm">{{ $t('challenge.admin.certificateHint') }}</p><div class="mt-6 grid items-end gap-4 sm:grid-cols-2 xl:grid-cols-[1fr_1fr_auto]"><div><label for="certificate-team" class="challenge-label">{{ $t('challenge.admin.team') }}</label><select id="certificate-team" v-model="certificateTeamId" class="challenge-field"><option v-for="row in rankings" :key="row.teamId" :value="row.teamId">{{ lt(state.teams.find(team => team.id === row.teamId)?.name) }}</option></select></div><div><label for="certificate-student" class="challenge-label">{{ $t('challenge.admin.student') }}</label><select id="certificate-student" v-model="certificateStudentId" class="challenge-field"><option v-for="student in certificateMembers" :key="student.id" :value="student.id">{{ lt(student.name) }}</option></select></div><button type="button" class="challenge-button-secondary" :disabled="!certificateTeamId || !certificateStudentId" @click="printCertificate"><AppIcon name="download" class="h-4 w-4" />{{ $t('challenge.admin.printCertificate') }}</button></div></section>
    <ChallengeTieBreakModal v-model="tieOpen" :team-ids="tiedTeamIds" />
  </div><ChallengePageSkeleton v-else />
</template>
